-- solution.sql — YOUR answer for: Exercise 1 — procedure with OUTPUT parameters: total salary of a department
-- Bài làm CỦA BẠN. Run order / thứ tự chạy: setup.sql → solution.sql → check.sql
USE DBI202_CL;
GO
CREATE OR ALTER PROCEDURE proc_SalaryOfDep
    @depNum INT,
    @total  DECIMAL(12,0) OUTPUT,
    @numEmp INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM tblDepartment WHERE depNum = @depNum)
        RETURN -1;                                      -- department not found
    SELECT @total  = COALESCE(SUM(empSalary), 0),
           @numEmp = COUNT(*)
    FROM tblEmployee
    WHERE depNum = @depNum;
    RETURN 0;
END

