-- solution.sql — YOUR answer for: Exercise 2 — procedure with a transaction: add an employee to a project, all or nothing
-- Bài làm CỦA BẠN. Run order / thứ tự chạy: setup.sql → solution.sql → check.sql
USE DBI202_CL;
GO
CREATE OR ALTER PROCEDURE proc_AddEmployeeToProject
    @empSSN  DECIMAL(18,0),
    @empName NVARCHAR(50),
    @salary  DECIMAL(10,0),
    @depNum  INT,
    @proNum  INT,
    @hours   DECIMAL(5,1),
    @msg     NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
            INSERT INTO tblEmployee (empSSN, empName, empSalary, depNum) VALUES (@empSSN, @empName, @salary, @depNum);
            INSERT INTO tblWorksOn (empSSN, proNum, workHours) VALUES (@empSSN, @proNum, @hours);
        COMMIT TRANSACTION;
        SET @msg = CONCAT(N'OK: ', @empName, N' added to project ', @proNum);
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;       -- undo BOTH inserts
        SET @msg = CONCAT(N'Error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
    END CATCH
END

