-- check.sql — self-check for: Exercises 3–4 — a scalar function and a table-valued function
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: fn_NumProjects: 003 → 3, 037 → 0
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(dbo.fn_NumProjects(30121050003) = 3 AND dbo.fn_NumProjects(30121050037) = 0, 1, 0); SET @info = CONCAT(N''got '', dbo.fn_NumProjects(30121050003), N'' and '', dbo.fn_NumProjects(30121050037));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. fn_NumProjects: 003 → 3, 037 → 0 | fn_NumProjects: 003 → 3, 037 → 0'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. fn_NumProjects: 003 → 3, 037 → 0 | fn_NumProjects: 003 → 3, 037 → 0', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: Employees on 2+ projects via the function
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;

DECLARE @a INT = (SELECT COUNT(*) FROM (SELECT empSSN FROM tblEmployee WHERE dbo.fn_NumProjects(empSSN) >= 2) AS a_), @b INT = (SELECT COUNT(*) FROM (SELECT empSSN FROM tblWorksOn GROUP BY empSSN HAVING COUNT(*) >= 2) AS b_);
SET @ok = IIF(@a = @b AND NOT EXISTS (SELECT empSSN FROM tblEmployee WHERE dbo.fn_NumProjects(empSSN) >= 2 EXCEPT SELECT empSSN FROM tblWorksOn GROUP BY empSSN HAVING COUNT(*) >= 2) AND NOT EXISTS (SELECT empSSN FROM tblWorksOn GROUP BY empSSN HAVING COUNT(*) >= 2 EXCEPT SELECT empSSN FROM tblEmployee WHERE dbo.fn_NumProjects(empSSN) >= 2), 1, 0);
SET @info = CONCAT(N''your result: '', @a, N'' rows; expected: '', @b, N'' rows'', IIF(@a = @b, N'' (same count, different values)'', N''''));
IF @@TRANCOUNT > 0 ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
